def is_job_enabled(job):
    if not job.is_released():
        return False
    if job.has_u_predecessor() and not job.u_predecessor.is_completed():
        return False
    if job.has_l_predecessor() and not job.l_predecessor.is_completed():
        return False
    return True

def is_pl_blocked(job):
    if not job.is_released():
        return False
    if job.has_l_predecessor() and not job.l_predecessor.is_completed():
        if job.has_u_predecessor() and not job.u_predecessor.is_completed():
            return True
    return False

def is_job_preempted(job, current_time):
    if not job.is_enabled(current_time):
        return False
    if job.is_suspending(current_time):
        return False
    if job.is_executing(current_time):
        return False
    return True

def calculate_preemption_time(job, start_time, end_time):
    total_preemption = 0
    for t in range(start_time, end_time):
        if is_job_preempted(job, t):
            total_preemption += 1
    return total_preemption

def is_idle_blocked(job, current_time, processor_states):
    if not is_pl_blocked(job, current_time):
        return False

    has_idle_processor = False
    for proc_state in processor_states:
        if proc_state.is_idle():
            has_idle_processor = True
            break
        if proc_state.running_job.priority < job.priority:
            has_idle_processor = True
            break

    return has_idle_processor

def calculate_idle_blocking_time(job, start_time, end_time, processor_states):
    total_idle_blocking = 0
    for t in range(start_time, end_time):
        if is_idle_blocked(job, t, processor_states):
            total_idle_blocking += 1
    return total_idle_blocking

def find_max_k_index(pipeline_task_i, k):
    if k == 0:
        return 1

    max_sum = -1
    max_index = -1

    for j in range(1, k + 1):
        current_sum = pipeline_task_i.subtasks[j-1].execution_time + pipeline_task_i.subtasks[j-1].suspension_time
        if current_sum > max_sum:
            max_sum = current_sum
            max_index = j

    return max_index

def calculate_suspension_ratios(task_set):
    max_s = 0
    for task in task_set:
        max_s = max(max_s, task.suspension_time)

    suspension_ratios = []
    for task in task_set:
        if max_s == 0: # Avoid division by zero if no suspensions
            xi_i = 1.0 # Or some other appropriate default
        else:
            xi_i = (max_s + task.execution_time) / max_s
        suspension_ratios.append(xi_i)

    max_xi = 0
    if suspension_ratios:
        max_xi = max(suspension_ratios)

    return max_s, max_xi

def is_ordinary_task(task):
    if task.has_suspensions:
        return False
    if task.is_pipeline:
        return False
    if task.has_non_preemptive_sections:
        return False
    return True
